$ErrorActionPreference = 'Stop'
New-Item -ItemType Directory -Force -Path 'C:\ssisdemo\packages' | Out-Null
New-Item -ItemType Directory -Force -Path 'C:\ssisdemo\csv' | Out-Null
New-Item -ItemType Directory -Force -Path 'C:\ssisdemo\logs' | Out-Null

function Write-B64([string]$path, [string]$b64) {
  [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($b64))
}

Write-B64 'C:\ssisdemo\packages\Load_Customers.dtsx'           ''
Write-B64 'C:\ssisdemo\packages\Load_Orders.dtsx'              ''
Write-B64 'C:\ssisdemo\packages\Load_Products_Scripted.dtsx'   ''
Write-B64 'C:\ssisdemo\csv\products_incoming.csv'              ''

Get-ChildItem -Recurse C:\ssisdemo\packages, C:\ssisdemo\csv | Select-Object FullName, Length | Format-Table -AutoSize | Out-String
